1	import { useState, useEffect, useRef } from "react";
2	import { motion, AnimatePresence } from "framer-motion";
3	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
4	import { QRCodeDisplay } from "@/components/qr-code-display";
5	import { apiRequest } from "@/lib/queryClient";
6	import { sseClient } from "@/lib/sse-client";
7	import { useToast } from "@/hooks/use-toast";
8	import { useDeviceStatusMonitoring, useSSEConnectionMonitoring } from "@/components/notification-system";
9	import { usePaymentReceivedToast } from "@/hooks/use-payment-received-toast";
10	import { getCurrentMerchantId } from "@/lib/auth";
