17	export default function MerchantTerminalMobile() {
18	  const [selectedStoneId, setSelectedStoneId] = useState<number | null>(null);
19	  const [successNotif, setSuccessNotif] = useState<{ id: string; message: string; amount?: string } | null>(null);
20	  const prevTransactionStatusRef = useRef<string | null>(null);
21	
22	  const [tapToPayStatus, setTapToPayStatus] = useState<"idle" | "waiting" | "processing" | "completed" | "failed">("idle");
23	  const [tapToPayApproved, setTapToPayApproved] = useState<boolean | null>(null);
24	  const [showTapToPayOverlay, setShowTapToPayOverlay] = useState(false);
25	
26	  const audioCtxRef = useRef<AudioContext | null>(null);
27	
28	  useEffect(() => {
29	    const AudioCtx: typeof AudioContext =
30	      window.AudioContext ||
31	      (window as Window & { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
32	    if (!AudioCtx) return;
33	    const ctx = new AudioCtx();
34	    audioCtxRef.current = ctx;
35	    const unlock = () => { if (ctx.state === "suspended") ctx.resume(); };
36	    window.addEventListener("click", unlock, { once: false });
37	    window.addEventListener("touchstart", unlock, { once: false });
38	    window.addEventListener("keydown", unlock, { once: false });
39	    return () => {
40	      window.removeEventListener("click", unlock);
41	      window.removeEventListener("touchstart", unlock);
42	      window.removeEventListener("keydown", unlock);
43	      ctx.close();
44	    };
45	  }, []);
46	
47	  const playSuccessChime = async () => {
48	    try {
49	      const ctx = audioCtxRef.current;
50	      if (!ctx) return;
51	      if (ctx.state === "suspended") await ctx.resume();
52	      const playTone = (freq: number, startTime: number, duration: number, gain: number) => {
53	        const osc = ctx.createOscillator();
54	        const gainNode = ctx.createGain();
55	        osc.connect(gainNode);
56	        gainNode.connect(ctx.destination);
57	        osc.type = "sine";
58	        osc.frequency.setValueAtTime(freq, startTime);
59	        gainNode.gain.setValueAtTime(0, startTime);
60	        gainNode.gain.linearRampToValueAtTime(gain, startTime + 0.018);
61	        gainNode.gain.exponentialRampToValueAtTime(0.001, startTime + duration);
62	        osc.start(startTime);
63	        osc.stop(startTime + duration);
64	      };
65	      const t = ctx.currentTime;
66	      playTone(523.25, t,        0.22, 0.28);
67	      playTone(659.25, t + 0.09, 0.22, 0.30);
68	      playTone(783.99, t + 0.18, 0.22, 0.30);
69	      playTone(1046.5, t + 0.27, 0.55, 0.36);
70	    } catch (e) { console.warn("Chime failed:", e); }
71	  };
72	
73	  const queryClient = useQueryClient();
74	  const { toast } = useToast();
75	  const merchantId = getCurrentMerchantId();
76	
77	  const { data: merchant } = useQuery({
78	    queryKey: ["/api/merchants", merchantId],
79	    queryFn: async () => {
80	      const r = await fetch(`/api/merchants/${merchantId}`);
81	      if (!r.ok) throw new Error("Failed to fetch merchant");
82	      return r.json();
83	    },
84	    enabled: !!merchantId,
85	  });
86	
87	  const { data: activeTransaction } = useQuery({
88	    queryKey: ["/api/merchants", merchantId, "active-transaction"],
89	    queryFn: async () => {
90	      const r = await fetch(`/api/merchants/${merchantId}/active-transaction`);
91	      if (!r.ok) throw new Error("Failed to fetch active transaction");
92	      return r.json();
93	    },
94	    // SSE keeps this cache live via queryClient.setQueryData — no polling needed.
95	    // A 30 s fallback refetch guards against SSE gaps (disconnect, reconnect lag).
96	    refetchInterval: 30000,
97	    enabled: !!merchantId,
98	  });
99	
100	  const { data: taptStones = [] } = useQuery({
101	    queryKey: ["/api/merchants", merchantId, "tapt-stones"],
102	    queryFn: async () => {
103	      const authToken = localStorage.getItem("authToken");
104	      const r = await fetch(`/api/merchants/${merchantId}/tapt-stones`, {
105	        headers: authToken ? { Authorization: `Bearer ${authToken}` } : {},
106	      });
107	      if (!r.ok) throw new Error("Failed to fetch tapt stones");
108	      return r.json();
109	    },
110	    enabled: !!merchantId,
111	  });
112	
113	  const { data: allTransactions = [] } = useQuery({
114	    queryKey: ["/api/merchants", merchantId, "transactions"],
115	    queryFn: async () => {
116	      const authToken = localStorage.getItem("authToken");
117	      const r = await fetch(`/api/merchants/${merchantId}/transactions`, {
118	        headers: authToken ? { Authorization: `Bearer ${authToken}` } : {},
119	      });
120	      if (!r.ok) throw new Error("Failed to fetch transactions");
121	      return r.json();
122	    },
123	    refetchInterval: 5000,
124	    enabled: !!merchantId,
125	  });
126	
127	  useEffect(() => {
128	    if ((taptStones as any[]).length > 0 && selectedStoneId === null) {
129	      setSelectedStoneId((taptStones as any[])[0].id);
130	    }
131	  }, [taptStones, selectedStoneId]);
132	
133	  useEffect(() => {
134	    if (!merchantId) return;
135	    sseClient.connect(merchantId);
136	    sseClient.subscribe("transaction_updated", (message) => {
137	      const tx = message.transaction ?? null;
138	      queryClient.setQueryData(["/api/merchants", merchantId, "active-transaction"], tx);
139	      // Keep allTransactions cache in sync for all updates so split progress,
140	      // status changes, and completedSplits increments appear immediately.
141	      if (tx) {
142	        queryClient.setQueryData<any[]>(
143	          ["/api/merchants", merchantId, "transactions"],
144	          (prev: any[] = []) => {
145	            const exists = prev.some((t: any) => t.id === tx.id);
146	            return exists
147	              ? prev.map((t: any) => (t.id === tx.id ? tx : t))
148	              : [tx, ...prev];
149	          }
150	        );
151	      }
152	    });
153	    return () => { sseClient.disconnect(); };
154	  }, [merchantId, queryClient]);
155	
156	  useDeviceStatusMonitoring();
157	  useSSEConnectionMonitoring(merchantId ?? 0);
158	  usePaymentReceivedToast();
159	
160	  useEffect(() => {
161	    const prev = prevTransactionStatusRef.current;
162	    const status = activeTransaction?.status ?? null;
163	    if (status === "completed" && prev && prev !== "completed") {
164	      playSuccessChime();
