172	  }, [activeTransaction?.status]);
173	
174	  const createTransactionMutation = useMutation({
175	    mutationFn: async (data: { itemName: string; price: string; selectedStoneId?: number; splitEnabled?: boolean }) => {
176	      const r = await apiRequest("POST", "/api/transactions", {
177	        merchantId,
178	        itemName: data.itemName,
179	        price: data.price,
180	        status: "pending",
181	        selectedStoneId: data.selectedStoneId,
182	        splitEnabled: data.splitEnabled ?? false,
183	      });
184	      return r.json();
185	    },
186	    onSuccess: () => {
187	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "active-transaction"] });
