314	
315	  // Terminal always resets to $0.00 after send — sent transactions live in the stack, not the pending display
316	  const sent = (allTransactions as any[])
317	    .filter((tx: any) => ["pending", "processing", "completed", "failed"].includes(tx.status))
318	    .slice(0, 10)
319	    .map((tx: any) => {
320	      let displayStatus: string;
321	      if (tx.status === "completed") displayStatus = "paid";
